void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096;
    // Aggressively update saved phases to local_best to guide search
    for (int i = 1; i <= vars; i++) {
        if (local_best[i] != 0)
            saved[i] = local_best[i];
    }
}
